using System;using System.Collections.Generic;using UnityEngine;
namespace AshenCrown.Progression{[Serializable]public class InventoryItem{public string id;public int amount;public int maxStack=99;public InventoryItem(){}public InventoryItem(string i,int a,int s=99){id=i;amount=Mathf.Max(0,a);maxStack=Mathf.Max(1,s);}}
public sealed class InventorySystem:MonoBehaviour{public static InventorySystem Instance{get;private set;}public event Action InventoryChanged;public IReadOnlyList<InventoryItem> Items=>items;[SerializeField]List<InventoryItem> items=new List<InventoryItem>();
void Awake(){if(Instance!=null&&Instance!=this){Destroy(gameObject);return;}Instance=this;DontDestroyOnLoad(gameObject);}public int GetAmount(string id){if(string.IsNullOrWhiteSpace(id))return 0;int total=0;foreach(var x in items)if(x!=null&&x.id==id)total+=Mathf.Max(0,x.amount);return total;}public bool Has(string id,int n=1)=>GetAmount(id)>=n;
public bool Add(string id,int n,int maxStack=99){if(string.IsNullOrWhiteSpace(id)||n<=0)return false;var x=Find(id);if(x==null){int a=Mathf.Min(n,maxStack);items.Add(new InventoryItem(id,a,maxStack));n-=a;}else{int a=Mathf.Min(n,Mathf.Max(0,x.maxStack-x.amount));x.amount+=a;n-=a;}while(n>0){int a=Mathf.Min(n,maxStack);items.Add(new InventoryItem(id,a,maxStack));n-=a;}InventoryChanged?.Invoke();return true;}
public bool Remove(string id,int n=1){if(!Has(id,n))return false;for(int i=items.Count-1;i>=0&&n>0;i--){if(items[i].id!=id)continue;int a=Mathf.Min(n,items[i].amount);items[i].amount-=a;n-=a;if(items[i].amount<=0)items.RemoveAt(i);}InventoryChanged?.Invoke();return true;}
public List<InventoryItem> Capture()=>new List<InventoryItem>(items);public void Restore(List<InventoryItem> x){items=x??new List<InventoryItem>();InventoryChanged?.Invoke();}public void Clear(){items.Clear();InventoryChanged?.Invoke();}InventoryItem Find(string id){foreach(var x in items)if(x!=null&&x.id==id&&x.amount>0)return x;return null;}}}